36	
37	    private Locality() {
38	    }
39	
40	    /**
41	     * @param city the owner's city
42	     * @return the canonical region for {@code city}, or {@code "UNKNOWN"} when the
43	     *         city is not in the table
44	     */
45	    public static String of(String city) {
46	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
47	    }
48	
49	    /**
50	     * Prefers the postcode: resolves the region by postcode range first (NSW
51	     * 2000-2099, VIC 3000-3099, QLD 4000-4099), and only falls back to the
52	     * city-to-region table when the postcode is absent or in no known range.
53	     *
54	     * @param city     the owner's city
55	     * @param postcode the owner's postcode, may be {@code null}
56	     * @return the canonical region, or {@code "UNKNOWN"} when neither resolves
57	     */
58	    public static String of(String city, String postcode) {
59	        String region = byPostcode(postcode);
60	        return region != null ? region : of(city);
61	    }
62	
63	    private static String byPostcode(String postcode) {
64	        if (postcode == null || !postcode.matches("\\d{4}")) {
65	            return null;
66	        }
67	        int value = Integer.parseInt(postcode);
68	        return REGION_POSTCODES.entrySet().stream()
69	            .filter(e -> value >= e.getValue()[0] && value <= e.getValue()[1])
70	            .map(Map.Entry::getKey)
