16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.time.LocalDate;
25	import java.util.*;
26	
27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	@EntityListeners(OwnerAuditListener.class)
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "city")
44	    @NotEmpty
45	    private String city;
46	
47	    @Column(name = "telephone")
48	    @NotEmpty
49	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Telephone must be in E.164 form, e.g. +61412345678")
50	    private String telephone;
51	
52	    @Column(name = "email")
53	    private String email;
54	
55	    @Column(name = "postcode")
56	    private String postcode;
57	
58	    @Column(name = "registration_date", columnDefinition = "DATE")
59	    private LocalDate registrationDate;
60	
61	    @Column(name = "customer_code")
62	    private String customerCode;
63	
64	    @Column(name = "namesake_count")
65	    private Integer namesakeCount;
66	
67	    @Column(name = "household_member_count")
68	    private Integer householdMemberCount;
69	
70	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
71	    private Set<Pet> pets;
72	
73	    /** Default an absent registration date to the server's current date on first persist. */
74	    @PrePersist
75	    void defaultRegistrationDate() {
76	        if (this.registrationDate == null) {
77	            this.registrationDate = LocalDate.now();
78	        }
79	    }
80	
81	    public LocalDate getRegistrationDate() {
82	        return this.registrationDate;
83	    }
84	
85	    public void setRegistrationDate(LocalDate registrationDate) {
86	        this.registrationDate = registrationDate;
87	    }
88	
89	    public String getCustomerCode() {
90	        return this.customerCode;
91	    }
92	
93	    /** Stable identifier shared by owners of the same household (matching last name and address). */
94	    @Transient
95	    public String getHouseholdId() {
96	        return HouseholdId.of(getLastName(), this.address);
97	    }
98	
99	    public void setCustomerCode(String customerCode) {
100	        this.customerCode = customerCode;
101	    }
102	
103	    /** Derived duplicate-detection key: normalized telephone, email (or empty) and household id
104	     *  joined with {@code '|'}. Two owners are duplicates only when their whole key matches, so a
105	     *  shared telephone alone (with matching email) is a collision regardless of household. */
106	    @Transient
107	    public String getIdentityKey() {
108	        return (this.telephone == null ? "" : this.telephone) + "|"
109	            + (this.email == null ? "" : this.email) + "|";
110	    }
111	
112	    /** Membership number formatted {@code <customerCode>-M<YY>}, e.g. {@code SMI-0007-M26}. */
113	    @Transient
114	    public String getMembershipNumber() {
115	        return MembershipNumber.of(this.customerCode, this.registrationDate);
116	    }
117	
118	    /** Luhn check digit over the digits of the {@code customerCode}. */
119	    @Transient
120	    public Integer getCheckDigit() {
121	        return CheckDigit.of(this.customerCode);
122	    }
123	
124	    public Integer getNamesakeCount() {
125	        return this.namesakeCount;
126	    }
127	
128	    public void setNamesakeCount(Integer namesakeCount) {
129	        this.namesakeCount = namesakeCount;
130	    }
131	
132	    /** Number of members in this owner's household (owners sharing {@link #getHouseholdId()})
133	     *  captured when the owner was created, including this owner. */
134	    public Integer getHouseholdMemberCount() {
135	        return this.householdMemberCount;
136	    }
137	
138	    public void setHouseholdMemberCount(Integer householdMemberCount) {
139	        this.householdMemberCount = householdMemberCount;
140	    }
141	
142	    public String getEmail() {
143	        return this.email;
144	    }
145	
146	    public void setEmail(String email) {
147	        this.email = email == null ? null : email.toLowerCase();
148	    }
149	
150	    public String getAddress() {
151	        return this.address;
152	    }
153	
154	    public void setAddress(String address) {
155	        this.address = AddressNormalizer.normalize(address);
156	    }
157	
158	    public String getPostcode() {
159	        return this.postcode;
160	    }
161	
162	    public void setPostcode(String postcode) {
163	        this.postcode = postcode;
164	    }
165	
166	    public String getCity() {
167	        return this.city;
168	    }
169	
170	    public void setCity(String city) {
171	        this.city = city;
172	    }
173	
174	    public String getTelephone() {
175	        return this.telephone;
176	    }
177	
178	    public void setTelephone(String telephone) {
179	        this.telephone = telephone == null ? null : PhoneNumbers.toE164(telephone);
180	    }
181	
182	    protected Set<Pet> getPetsInternal() {
183	        if (this.pets == null) {
184	            this.pets = new HashSet<>();
185	        }
186	        return this.pets;
187	    }
188	
189	    protected void setPetsInternal(Set<Pet> pets) {
190	        this.pets = pets;
191	    }
192	
193	    public List<Pet> getPets() {
194	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
195	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
196	        return Collections.unmodifiableList(sortedPets);
197	    }
198	
199	    public void setPets(List<Pet> pets) {
200	        this.pets = new HashSet<>(pets);
201	    }
202	
203	    public void addPet(Pet pet) {
204	        getPetsInternal().add(pet);
205	        pet.setOwner(this);
206	    }
207	
208	    /**
209	     * Return the Pet with the given name, or null if none found for this Owner.
210	     *
211	     * @param name to test
212	     * @return true if pet name is already in use
213	     */
214	    public Pet getPet(String name) {
215	        return getPet(name, false);
216	    }
217	
218	    /**
219	     * Return the Pet with the given name, or null if none found for this Owner.
220	     *
221	     * @param name to test
222	     * @return true if pet name is already in use
223	     */
224	    public Pet getPet(String name, boolean ignoreNew) {
225	        name = name.toLowerCase();
226	        for (Pet pet : getPetsInternal()) {
227	            if (!ignoreNew || !pet.isNew()) {
228	                String compName = pet.getName();
229	                compName = compName.toLowerCase();
230	                if (compName.equals(name)) {
231	                    return pet;
232	                }
233	            }
234	        }
235	        return null;
236	    }
237	
238	    public Pet getPet(Integer petId) {
239	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
240	    }
241	
242	    @Override
243	    public String toString() {
244	        return new ToStringCreator(this)
245	
246	            .append("id", this.getId())
247	            .append("new", this.isNew())
248	            .append("lastName", this.getLastName())
249	            .append("firstName", this.getFirstName())
250	            .append("address", this.address)
251	            .append("city", this.city)
252	            .append("telephone", this.telephone)
253	            .toString();
254	    }
255	}
